window.GNN_LESSONS=window.GNN_LESSONS||{};window.GNN_LESSONS["L0"]={"deck":"L0","slides":[{"p":1,"title":"표지: 그래프 신경망 오리엔테이션","terms":["Orientation","Graph Neural Network","Node","Edge"],"pass1":[{"kind":"say","lines":["첫 장은 이 수업의 표지예요.","본격적인 공부 전에 수업을 안내하는 시간, 이걸 **오리엔테이션(Orientation)**이라고 해요.","무엇을 배우는지, 성적은 어떻게 매기는지, 누구에게 묻는지 알려 줘요."]},{"kind":"figure","head":"점과 선으로 친구 관계 그리기","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<line class=\"e b2\" x1=\"90\" y1=\"80\" x2=\"210\" y2=\"55\"/>\n<line class=\"e b2\" x1=\"90\" y1=\"80\" x2=\"150\" y2=\"165\"/>\n<line class=\"e b2\" x1=\"210\" y1=\"55\" x2=\"150\" y2=\"165\"/>\n<line class=\"e b2\" x1=\"210\" y1=\"55\" x2=\"320\" y2=\"110\"/>\n<line class=\"e b2\" x1=\"320\" y1=\"110\" x2=\"400\" y2=\"180\"/>\n<circle class=\"n b1\" cx=\"90\" cy=\"80\" r=\"24\"/>\n<text class=\"tl b1\" x=\"90\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">민수<\/text>\n<circle class=\"n b1\" cx=\"210\" cy=\"55\" r=\"24\"/>\n<text class=\"tl b1\" x=\"210\" y=\"60\" font-size=\"14\" text-anchor=\"middle\">지우<\/text>\n<circle class=\"n b1\" cx=\"150\" cy=\"165\" r=\"24\"/>\n<text class=\"tl b1\" x=\"150\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">서연<\/text>\n<circle class=\"n b1\" cx=\"320\" cy=\"110\" r=\"24\"/>\n<text class=\"tl b1\" x=\"320\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">하준<\/text>\n<circle class=\"n b1\" cx=\"400\" cy=\"180\" r=\"24\"/>\n<text class=\"tl b1\" x=\"400\" y=\"185\" font-size=\"14\" text-anchor=\"middle\">도윤<\/text>\n<text class=\"tb b1\" x=\"240\" y=\"230\" font-size=\"14\" text-anchor=\"middle\">동그라미 하나는 사람 한 명이에요. 이게 노드예요.<\/text>\n<text class=\"tb b2\" x=\"240\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">선 하나는 두 사람이 친구라는 뜻이에요. 이게 엣지예요.<\/text>\n<\/svg>","caption":"친구 다섯 명의 관계를 동그라미와 선으로 그렸어요. 이런 그림을 그래프라고 해요.","builds":2},{"kind":"say","lines":["표지 오른쪽 그림도 이렇게 점과 선이 잔뜩 이어진 모양이에요.","점 하나를 **노드(Node)**, 두 점을 잇는 선을 **엣지(Edge)**라고 해요.","신경망은 예시를 많이 보고 스스로 규칙을 익히는 컴퓨터 프로그램이에요.","그래프를 다루는 신경망, 이게 **그래프 신경망(Graph Neural Network)**이고 줄여서 GNN이라고 해요."]}],"pass2":[{"kind":"look","head":"표지에서 볼 곳","boxes":[{"x":0.06,"y":0.17,"w":0.54,"h":0.19,"say":"제목: **그래프 신경망(Graph Neural Network)** 오리엔테이션이에요."},{"x":0.22,"y":0.48,"w":0.2,"h":0.08,"say":"담당 교수님: 이오준 교수님(Prof. O-Joun Lee)이에요."},{"x":0.18,"y":0.57,"w":0.23,"h":0.1,"say":"소속: 가톨릭대학교 인공지능학과 네트워크 과학 연구실이에요."},{"x":0.2,"y":0.73,"w":0.26,"h":0.06,"say":"이메일: ojlee@catholic.ac.kr 이에요."},{"x":0.66,"y":0.0,"w":0.34,"h":1.0,"say":"오른쪽 그림의 점은 **노드(Node)**, 선은 **엣지(Edge)**를 떠올리게 해요."}]},{"kind":"say","lines":["**그래프 신경망(Graph Neural Network)**은 그래프를 다루는 신경망이에요.","그래프는 **노드(Node)**와 그 사이를 잇는 **엣지(Edge)**로 된 데이터예요."]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["이번 학기는 인공 신경망으로 그래프 데이터를 다루는 수업이래요.","그래프는 노드와 노드 사이의 연결로 이루어진 데이터예요.","표 같은 정해진 형태로 담기 힘든 데이터도 그래프로 나타내면 처리하기 쉬워진대요."]}],"pass3":[],"pass4":[]},{"p":2,"title":"목차","terms":["Orientation","Assignment","Teaching Assistant"],"pass1":[{"kind":"say","lines":["목차에는 일곱 항목이 있어요.","크게 묶으면 세 가지 이야기예요.","무엇을 배우는지, 성적을 어떻게 받는지, 궁금할 때 누구에게 묻는지예요."]},{"kind":"figure","head":"목차를 세 묶음으로 나누기","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb\" x=\"240\" y=\"30\" font-size=\"18\" text-anchor=\"middle\">목차 일곱 항목을 세 묶음으로<\/text>\n<rect class=\"box b1\" x=\"10\" y=\"50\" width=\"146\" height=\"200\" rx=\"12\"/>\n<text class=\"tb b1\" x=\"83\" y=\"84\" font-size=\"17\" text-anchor=\"middle\">무엇을 배우나<\/text>\n<text class=\"t b1\" x=\"83\" y=\"132\" font-size=\"15\" text-anchor=\"middle\">강의 소개<\/text>\n<text class=\"t b1\" x=\"83\" y=\"167\" font-size=\"15\" text-anchor=\"middle\">참고 도서<\/text>\n<text class=\"t b1\" x=\"83\" y=\"202\" font-size=\"15\" text-anchor=\"middle\">강의 일정<\/text>\n<rect class=\"box b2\" x=\"167\" y=\"50\" width=\"146\" height=\"200\" rx=\"12\"/>\n<text class=\"tb b2\" x=\"240\" y=\"84\" font-size=\"17\" text-anchor=\"middle\">어떻게 평가받나<\/text>\n<text class=\"t b2\" x=\"240\" y=\"140\" font-size=\"15\" text-anchor=\"middle\">평가 기준<\/text>\n<text class=\"t b2\" x=\"240\" y=\"180\" font-size=\"15\" text-anchor=\"middle\">과제<\/text>\n<rect class=\"box b3\" x=\"324\" y=\"50\" width=\"146\" height=\"200\" rx=\"12\"/>\n<text class=\"tb b3\" x=\"397\" y=\"84\" font-size=\"17\" text-anchor=\"middle\">누구에게 묻나<\/text>\n<text class=\"t b3\" x=\"397\" y=\"140\" font-size=\"15\" text-anchor=\"middle\">교수님<\/text>\n<text class=\"t b3\" x=\"397\" y=\"180\" font-size=\"15\" text-anchor=\"middle\">조교님<\/text>\n<text class=\"tm b3\" x=\"397\" y=\"202\" font-size=\"13\" text-anchor=\"middle\">(수업 도우미)<\/text>\n<\/svg>","caption":"목차 일곱 항목을 세 묶음으로 나눠 봤어요.","builds":3}],"pass2":[{"kind":"look","head":"목차 일곱 항목","boxes":[{"x":0.04,"y":0.12,"w":0.16,"h":0.07,"say":"이 슬라이드는 **오리엔테이션(Orientation)**의 목차예요."},{"x":0.26,"y":0.13,"w":0.3,"h":0.26,"say":"앞의 셋은 무엇을 배우나예요. 강의 소개, 참고 도서, 16주 강의 일정."},{"x":0.26,"y":0.43,"w":0.2,"h":0.17,"say":"가운데 둘은 어떻게 평가받나예요. 평가 비율과 **과제(Assignment)**."},{"x":0.26,"y":0.63,"w":0.2,"h":0.18,"say":"마지막 둘은 누구에게 묻나예요. 교수님과 **조교(Teaching Assistant)**."}]},{"kind":"points","head":"무엇이 제일 중요할까","items":["공부에 제일 중요한 건 강의 일정이에요. 16주 동안 매주 배울 주제예요.","성적에 제일 중요한 건 **과제(Assignment)**예요. 이유는 p.11 에서 나와요."]}],"pass3":[{"kind":"warn","head":"슬라이드 오타","items":["영어 원본 마지막 항목이 \"Informationl\" 로 적혀 있어요. \"Information\" 의 오타예요."]},{"kind":"check","q":"**오리엔테이션(Orientation)**은 무엇을 하는 시간일까요?","choices":["첫 시험을 보는 시간","수업이 무엇을 배우고 어떻게 평가하는지 안내하는 시간","과제를 제출하는 시간"],"a":1,"why":"**오리엔테이션(Orientation)**은 본격적인 공부 전에 수업 내용, 평가, 연락처를 안내하는 시간이에요."}],"pass4":[]},{"p":3,"title":"이 강의에 대하여: 목표","terms":["Graph Neural Network","Graph Convolutional Network","Graph Attention Network","Graph Pooling","Heterogeneous Graph","Graph Transformer","Knowledge Graph","GraphRAG"],"pass1":[{"kind":"say","lines":["이 쪽은 이 수업이 무엇을 목표로 하는지 적어 둔 곳이에요.","**그래프 신경망(Graph Neural Network)**을 기초부터 최신 방법, 실제 쓰임새까지 배워요.","화요일에는 설명을 듣고, 목요일에는 직접 코드를 돌려 보는 실습을 해요."]},{"kind":"analogy","head":"재료마다 맞는 칼이 따로 있어요","scene":"주방에는 재료마다 맞는 칼이 있어요. 빵은 빵칼로, 생선은 생선칼로 잘라요. 그런데 친구 관계망, 도로망처럼 연결이 핵심인 재료는 예전 칼로 잘 안 잘려요. 그래서 연결로 된 자료 전용 칼을 새로 만든 게 그래프 신경망이에요.","map":[["빵, 생선 같은 재료","사진, 문장 같은 여러 자료"],["재료마다 맞는 칼","자료마다 맞는 컴퓨터 계산 방법"],["연결이 핵심인 재료","그래프(점과 선으로 된 자료)"],["연결 자료 전용 새 칼","**그래프 신경망(Graph Neural Network)**"]]},{"kind":"say","lines":["슬라이드에 GCN, GAT 같은 영어 이름이 줄줄이 나오죠?","모두 그래프 신경망의 한 종류, 즉 모델 이름이에요.","모델은 컴퓨터가 문제를 푸는 계산 방법 하나를 말해요. 지금은 이름만 봐 두세요."]}],"pass2":[{"kind":"look","head":"목표 슬라이드의 세 불릿","boxes":[{"x":0.02,"y":0.22,"w":0.95,"h":0.14,"say":"첫 불릿: GNN을 깊이 탐구해요. 기초, 최신(State-Of-The-Art) 모델, 실제 응용까지요."},{"x":0.02,"y":0.44,"w":0.97,"h":0.19,"say":"둘째 불릿: 배우는 순서예요. GCN에서 출발해 GAT, GCNII, 트랜스포머로 나아가요."},{"x":0.02,"y":0.71,"w":0.95,"h":0.15,"say":"셋째 불릿: 수업 방식이에요. 이론 강의, 실습, 코딩 과제를 섞어요."}]},{"kind":"points","head":"둘째 불릿의 모델 이름 풀기","items":["**그래프 합성곱 신경망(Graph Convolutional Network)**: 이웃 정보를 평균 내듯 섞어 나를 새로 표현하는 가장 기본 GNN이에요.","**그래프 어텐션 네트워크(Graph Attention Network)**: 이웃마다 중요도를 다르게 줘요.","**그래프 풀링(Graph Pooling)**: 노드 여러 개를 묶어 그래프를 줄여요.","**이종 그래프(Heterogeneous Graph)**: 노드나 엣지 종류가 여러 개인 그래프예요.","**그래프 트랜스포머(Graph Transformer)**: 트랜스포머를 그래프에 쓰는 모델이에요."]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["수업은 기본적으로 화요일은 이론, 목요일은 실습이래요.","화요일에 배운 내용으로 목요일에 간단한 실습을 해요.","실습이 끝나면 그 내용으로 간단한 프로그래밍 과제가 나와요."]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["요즘 **지식 그래프(Knowledge Graph)**, **그래프 검색 증강 생성(GraphRAG)** 같은 게 트렌드래요.","그래서 실생활에서도 그래프 이야기를 많이 듣게 되었대요."]},{"kind":"mining","src":"마이닝 0강 Orientation","lines":["지난 학기 마이닝은 그래프의 성질과 구조를 재는 지표, 분석 방법을 배웠어요.","예: 중요한 노드 찾기(중심성), 무리 찾기(커뮤니티), 링크 예측.","이번 학기는 신경망이 그래프에서 스스로 특징을 배우게 해요."]}],"pass3":[{"kind":"warn","head":"목표와 일정표가 딱 맞지는 않아요","items":["구조 보존 GNN, 동적 그래프 같은 이름은 16주 일정표(p.6~p.10)와 딱 맞지 않아요.","목표는 큰 방향이에요. 매주 공부 계획은 일정표 기준으로 세우세요."]},{"kind":"english","head":"GNN을 한 문장으로","en":"Graph Neural Networks are neural networks that take graphs of nodes and edges as input.","ko":"그래프 신경망은 노드와 엣지로 된 그래프를 입력으로 받는 신경망이다.","tip":"nodes and edges 를 꼭 넣으세요."}],"pass4":[]},{"p":4,"title":"이 강의에 대하여: 배우고 나면 할 수 있는 것","terms":["Graph Neural Network","Adjacency Matrix","Over-smoothing","Graph Convolutional Network","Graph Attention Network"],"pass1":[{"kind":"say","lines":["이 쪽에는 수업이 끝나면 할 수 있게 되는 일 일곱 가지가 적혀 있어요.","줄여 말하면 이해하고, 직접 만들고, 서로 비교할 수 있게 된다는 뜻이에요."]},{"kind":"points","head":"세 가지를 쉬운 말로 풀면","items":["이해하기: 그래프 신경망이 속에서 어떤 계산을 하는지 알게 돼요.","만들기: 목요일 실습에서 직접 코드를 돌려 그래프 신경망을 만들어 봐요.","비교하기: 여러 방법 중 무엇이 어디에 좋고 어디서 약한지 말할 수 있어요.","쓰이는 곳의 예로 쇼핑몰 상품 추천, SNS 친구 관계 분석이 나와요."]}],"pass2":[{"kind":"look","head":"일곱 가지 목표","boxes":[{"x":0.04,"y":0.24,"w":0.6,"h":0.05,"say":"첫 줄: 강의를 마치면 학생들은 다음을 할 수 있게 된대요."},{"x":0.08,"y":0.3,"w":0.78,"h":0.11,"say":"1, 2번: 그래프 기초와 GCN, GAT, 그래프 트랜스포머의 구조, 학습, 활용을 이해해요."},{"x":0.08,"y":0.47,"w":0.6,"h":0.11,"say":"3, 4번: GNN을 직접 만들고, 지금 GNN의 한계와 해결책을 알아요."},{"x":0.08,"y":0.595,"w":0.69,"h":0.05,"say":"5번: 성능, 적용 가능성, 한계로 모델들을 비교해요."},{"x":0.08,"y":0.65,"w":0.8,"h":0.11,"say":"6, 7번: 최신 연구를 따라가고, 추천, 생물정보학 등 여러 분야에 적용해요."},{"x":0.04,"y":0.83,"w":0.9,"h":0.1,"say":"마지막 불릿: 자기 프로젝트나 연구에 GNN을 구현할 수 있어야 해요."}]},{"kind":"points","head":"목표 속 낯선 말 풀기","items":["**인접행렬(Adjacency Matrix)**: 누가 누구와 연결됐는지 0과 1로 적은 표예요.","구조(architecture), 학습(training), 활용(use): 어떻게 계산하고, 가르치고, 어디에 쓰나예요.","한계의 예: 층을 깊게 쌓으면 노드들이 다 비슷해지는 **과잉 평활화(Over-smoothing)**예요."]},{"kind":"figure","head":"세 동사와 성적","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">일곱 목표를 세 동사로<\/text>\n<rect class=\"box b1\" x=\"10\" y=\"38\" width=\"140\" height=\"80\" rx=\"10\"/>\n<text class=\"tb b1\" x=\"80\" y=\"72\" font-size=\"18\" text-anchor=\"middle\">이해한다<\/text>\n<text class=\"tm b1\" x=\"80\" y=\"100\" font-size=\"14\" text-anchor=\"middle\">목표 1, 2, 4<\/text>\n<rect class=\"box b1\" x=\"170\" y=\"38\" width=\"140\" height=\"80\" rx=\"10\"/>\n<text class=\"tb b1\" x=\"240\" y=\"72\" font-size=\"18\" text-anchor=\"middle\">만든다<\/text>\n<text class=\"tm b1\" x=\"240\" y=\"100\" font-size=\"14\" text-anchor=\"middle\">목표 3, 7<\/text>\n<rect class=\"box b1\" x=\"330\" y=\"38\" width=\"140\" height=\"80\" rx=\"10\"/>\n<text class=\"tb b1\" x=\"400\" y=\"72\" font-size=\"18\" text-anchor=\"middle\">비교한다<\/text>\n<text class=\"tm b1\" x=\"400\" y=\"100\" font-size=\"14\" text-anchor=\"middle\">목표 5, 6<\/text>\n<line class=\"e b2\" x1=\"80\" y1=\"122\" x2=\"80\" y2=\"158\"/>\n<polygon class=\"arrow b2\" points=\"80,168 74,156 86,156\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"122\" x2=\"240\" y2=\"158\"/>\n<polygon class=\"arrow b2\" points=\"240,168 234,156 246,156\"/>\n<line class=\"e b2\" x1=\"400\" y1=\"122\" x2=\"400\" y2=\"158\"/>\n<polygon class=\"arrow b2\" points=\"400,168 394,156 406,156\"/>\n<rect class=\"box2 b2\" x=\"10\" y=\"172\" width=\"140\" height=\"80\" rx=\"10\"/>\n<text class=\"tb b2\" x=\"80\" y=\"205\" font-size=\"16\" text-anchor=\"middle\">계산 문제<\/text>\n<text class=\"t b2\" x=\"80\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">메커니즘을 숫자로<\/text>\n<rect class=\"box2 b2\" x=\"170\" y=\"172\" width=\"140\" height=\"80\" rx=\"10\"/>\n<text class=\"tb b2\" x=\"240\" y=\"205\" font-size=\"16\" text-anchor=\"middle\">과제 30%<\/text>\n<text class=\"t b2\" x=\"240\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">매주 .ipynb 제출<\/text>\n<rect class=\"box2 b2\" x=\"330\" y=\"172\" width=\"140\" height=\"80\" rx=\"10\"/>\n<text class=\"tb b2\" x=\"400\" y=\"205\" font-size=\"16\" text-anchor=\"middle\">서술 문제<\/text>\n<text class=\"t b2\" x=\"400\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">장단점, 특징<\/text>\n<\/svg>","caption":"이해는 계산 문제로, 만들기는 과제로, 비교는 서술 문제로 확인받아요.","builds":2},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["GNN을 배운 다음, GNN의 한계를 극복하거나 확장하는 기술 방향들을 다룬대요.","새 모델이 나오면 먼저 물어보세요. 앞 모델의 어떤 한계를 고치려고 나왔지?"]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 10번 (GAT) (a)","q":"What problem in traditional GCNs does GAT aim to solve?","qko":"기존 GCN의 어떤 문제를 GAT가 풀려고 했나요?","solve":["이 문제는 (a) 서술, (b) 어텐션 계수 계산, (c) 노드 A 새 특징 계산으로 된 세트예요.","먼저 **그래프 합성곱 신경망(Graph Convolutional Network)**이 이웃을 어떻게 섞는지 떠올려요.","GCN은 차수로 정해진 고정 가중치로 이웃을 똑같이 다뤄요.","**그래프 어텐션 네트워크(Graph Attention Network)**는 이웃마다 다른 중요도를 학습해요.","두 모델을 한 문장 안에서 대비해 영어로 써요."],"answer":"GCN treats all neighbors with fixed weights based on node degree, while GAT learns a different importance weight for each neighbor."},{"kind":"check","q":"목표 5번 \"성능, 적용 가능성, 한계로 비교한다\"는 시험의 어떤 모양과 이어질까요?","choices":["계산 문제","서술 문제","출석 점수"],"a":1,"why":"비교하고 장단점을 쓰는 건 서술 문제예요. 이해는 계산 문제, 만들기는 과제로 확인받아요."}],"pass4":[]},{"p":5,"title":"참고 도서","terms":["Graph Neural Network","GraphRAG"],"pass1":[{"kind":"say","lines":["이 쪽은 어떤 책으로 공부하면 되는지 알려 줘요. 교재는 살 필요가 없어요.","학교 사이트에 PDF 파일로 올라오는 강의 슬라이드가 교재 역할을 해요.","교수님은 강의 자료가 책보다 더 새로운 내용이라서 그렇다고 했어요.","슬라이드에 나온 책 두 권은 막힐 때 찾아보는 사전처럼 쓰면 돼요."]}],"pass2":[{"kind":"look","head":"참고 도서 슬라이드","boxes":[{"x":0.04,"y":0.14,"w":0.56,"h":0.12,"say":"위 두 줄: 교재를 살 필요 없고, 자료는 PDF 같은 디지털 형식으로 줘요."},{"x":0.02,"y":0.3,"w":0.82,"h":0.29,"say":"교재 칸: 참고용 책 두 권이에요. 2022년 책과 2020년 책이에요."},{"x":0.27,"y":0.6,"w":0.13,"h":0.34,"say":"파란 표지: Wu 외 \"Graph Neural Networks: Foundations, Frontiers, and Applications\"."},{"x":0.47,"y":0.6,"w":0.155,"h":0.34,"say":"빨간 표지: Liu, Zhou \"Introduction to Graph Neural Networks\" 입문서예요."}]},{"kind":"points","head":"책 쓰는 법","items":["슬라이드만으로 이해가 안 되는 모델이 있으면 책 목차에서 모델 이름을 찾아 읽어요.","첫 책은 **그래프 신경망(Graph Neural Network)**의 기초, 최전선 연구, 응용을 모은 두꺼운 책이에요."]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["교재는 굳이 구입할 필요 없다고 두 번이나 말했어요.","강의 자료가 책보다 훨씬 업데이트된 내용이라서래요.","강의 자료를 바탕으로 열심히 공부하라고 했어요."]},{"kind":"mining","src":"마이닝 0강 Orientation","lines":["지난 학기 마이닝 OT도 교재를 살 필요 없고 자료는 PDF로 준다고 했어요.","그때 참고 도서는 Hamilton, Easley와 Kleinberg, Barabási 책이었어요.","이번 학기는 GNN 전문 책 두 권으로 바뀌었어요."]}],"pass3":[{"kind":"warn","head":"무엇을 기준으로 공부하나","items":["책은 2020년, 2022년 책이라 **그래프 검색 증강 생성(GraphRAG)**, 그래프 확산 모델 같은 최근 주제는 없거나 짧을 수 있어요.","교수님이 올해 슬라이드를 많이 바꿨어요. 선배들 예전 자료보다 올해 슬라이드가 기준이에요."]}],"pass4":[]},{"p":6,"title":"강의 일정 1부: 기초와 핵심 구조 (1~3주)","terms":["Node","Edge","Adjacency Matrix","Centrality","Heterogeneous Graph","Embedding","Message Passing","Graph Convolutional Network","Expressive Power","Weisfeiler-Lehman Test"],"pass1":[{"kind":"say","lines":["이제 16주 동안 무엇을 배우는지 적힌 순서표예요. 크게 네 부분이에요.","1부는 기초예요. 1주차에는 점과 선으로 된 그래프를 복습해요.","2주차에는 그래프 신경망이 실제로 어떻게 계산하는지 배워요.","3주차에는 그래프 신경망이 서로 다른 그래프를 어디까지 구별하는지 봐요."]},{"kind":"analogy","head":"친구들에게 들은 이야기로 내 생각 고치기","scene":"나에게는 친한 친구가 3명 있어요. 나는 내 생각은 알지만, 오늘 반에서 무슨 일이 있었는지는 몰라요. 그래서 친구 3명에게 들은 이야기를 모아 내 생각과 합쳐 고쳐요. 친구는 가까이 있어 나와 관련된 일을 잘 알아서 이 방법이 통해요.","map":[["나와 선으로 이어진 친구","이웃 노드"],["친구 한 명이 들려주는 이야기","메시지(이웃이 보내는 정보)"],["이야기 여러 개를 모아 내 생각 고치기","모으기(집계)와 새로 고치기(업데이트)"],["이 과정 전체","**메시지 패싱(Message Passing)**"]]},{"kind":"say","lines":["이렇게 이웃에게 듣고, 모으고, 나를 고치는 과정을 **메시지 패싱(Message Passing)**이라고 해요.","2주차에 배우는 그래프 신경망의 기본 틀이에요.","그리고 서로 다른 그래프를 구별해 내는 힘을 **표현력(Expressive Power)**이라고 해요."]}],"pass2":[{"kind":"look","head":"1부: 기초와 핵심 구조","boxes":[{"x":0.03,"y":0.12,"w":0.2,"h":0.05,"say":"1부 제목: 기초와 핵심 구조예요."},{"x":0.07,"y":0.18,"w":0.65,"h":0.28,"say":"1주차: 그래프 기초와 전통적 임베딩. 지난 학기 마이닝 복습이에요."},{"x":0.07,"y":0.47,"w":0.45,"h":0.22,"say":"2주차: CNN에서 GNN으로, 메시지 패싱 신경망(MPNN), GCN이에요."},{"x":0.07,"y":0.69,"w":0.45,"h":0.17,"say":"3주차: GNN의 표현력. 1-WL 동형 테스트, 고차 GNN, 서브그래프 GNN이에요."}]},{"kind":"points","head":"1주차 용어 풀기","items":["**노드(Node)**는 점(사람, 원자), **엣지(Edge)**는 선(친구 관계, 결합)이에요.","**인접행렬(Adjacency Matrix)**: 연결을 0과 1로 적은 표. 0 아닌 칸만 저장하면 희소 행렬이에요.","**중심성(Centrality)**: 누가 중요한 노드인지 재는 점수예요. 그래프 커널은 두 그래프가 닮은 정도예요.","**이종 그래프(Heterogeneous Graph)**: 저자, 논문, 학회처럼 노드 종류가 여러 개예요.","얕은 **임베딩(Embedding)**: 신경망 층 없이 노드마다 숫자 벡터를 하나씩 외워 둬요(DeepWalk, Node2Vec).","벡터는 숫자 여러 개를 한 줄로 늘어놓은 묶음이에요. 예를 들어 노드 하나를 숫자 세 개로 적는 식이에요."]},{"kind":"points","head":"2, 3주차 용어 풀기","items":["CNN에서 GNN으로: 사진 픽셀은 격자지만, 그래프는 이웃 수도 순서도 제각각이에요.","**메시지 패싱(Message Passing)**: 이웃에게 받고, 모으고, 나와 합쳐 고치는 GNN 공통 틀이에요.","**그래프 합성곱 신경망(Graph Convolutional Network)**: 메시지 패싱의 대표 모델이에요.","**바이스파일러-레만 검정(Weisfeiler-Lehman Test)**: 두 그래프가 같은 모양인지 판별해요. **표현력(Expressive Power)**의 잣대예요."]},{"kind":"figure","head":"16주 로드맵","svg":"<svg viewBox=\"0 0 480 300\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect class=\"box2 b1\" x=\"4\" y=\"20\" width=\"72\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b1\" x=\"40\" y=\"44\" font-size=\"15\" text-anchor=\"middle\">1부<\/text>\n<text class=\"t b1\" x=\"40\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">기초<\/text>\n<rect class=\"box b1\" x=\"82\" y=\"20\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b1\" x=\"120\" y=\"43\" font-size=\"15\" text-anchor=\"middle\">1주<\/text>\n<text class=\"t b1\" x=\"120\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">그래프<\/text>\n<rect class=\"box b1\" x=\"162\" y=\"20\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b1\" x=\"200\" y=\"43\" font-size=\"15\" text-anchor=\"middle\">2주<\/text>\n<text class=\"t b1\" x=\"200\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">MPNN, GCN<\/text>\n<rect class=\"box2 b1\" x=\"242\" y=\"20\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b1\" x=\"280\" y=\"43\" font-size=\"15\" text-anchor=\"middle\">3주<\/text>\n<text class=\"t b1\" x=\"280\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">표현력<\/text>\n<rect class=\"box2 b2\" x=\"4\" y=\"90\" width=\"72\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"40\" y=\"114\" font-size=\"15\" text-anchor=\"middle\">2부<\/text>\n<text class=\"t b2\" x=\"40\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">병목<\/text>\n<rect class=\"box2 b2\" x=\"82\" y=\"90\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"120\" y=\"113\" font-size=\"15\" text-anchor=\"middle\">4주<\/text>\n<text class=\"t b2\" x=\"120\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">깊은 GNN<\/text>\n<rect class=\"box2 b2\" x=\"162\" y=\"90\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"200\" y=\"113\" font-size=\"15\" text-anchor=\"middle\">5주<\/text>\n<text class=\"t b2\" x=\"200\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">어텐션<\/text>\n<rect class=\"box2 b2\" x=\"242\" y=\"90\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"280\" y=\"113\" font-size=\"15\" text-anchor=\"middle\">6주<\/text>\n<text class=\"t b2\" x=\"280\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">확장성<\/text>\n<rect class=\"box2 b2\" x=\"322\" y=\"90\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"360\" y=\"113\" font-size=\"15\" text-anchor=\"middle\">7주<\/text>\n<text class=\"t b2\" x=\"360\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">설명, 강건<\/text>\n<rect class=\"box2 b2\" x=\"402\" y=\"90\" width=\"76\" height=\"56\" rx=\"8\"/>\n<rect class=\"hl b2\" x=\"402\" y=\"90\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b2\" x=\"440\" y=\"113\" font-size=\"15\" text-anchor=\"middle\">8주<\/text>\n<text class=\"tb b2\" x=\"440\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">중간고사<\/text>\n<rect class=\"box2 b3\" x=\"4\" y=\"160\" width=\"72\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b3\" x=\"40\" y=\"184\" font-size=\"15\" text-anchor=\"middle\">3부<\/text>\n<text class=\"t b3\" x=\"40\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">고급<\/text>\n<rect class=\"box2 b3\" x=\"82\" y=\"160\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b3\" x=\"120\" y=\"183\" font-size=\"15\" text-anchor=\"middle\">9주<\/text>\n<text class=\"t b3\" x=\"120\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">트랜스포머<\/text>\n<rect class=\"box2 b3\" x=\"162\" y=\"160\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b3\" x=\"200\" y=\"183\" font-size=\"15\" text-anchor=\"middle\">10주<\/text>\n<text class=\"t b3\" x=\"200\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">생성, 확산<\/text>\n<rect class=\"box b3\" x=\"242\" y=\"160\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b3\" x=\"280\" y=\"183\" font-size=\"15\" text-anchor=\"middle\">11주<\/text>\n<text class=\"t b3\" x=\"280\" y=\"205\" font-size=\"14\" text-anchor=\"middle\">시공간<\/text>\n<rect class=\"box2 b4\" x=\"4\" y=\"230\" width=\"72\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b4\" x=\"40\" y=\"254\" font-size=\"15\" text-anchor=\"middle\">4부<\/text>\n<text class=\"t b4\" x=\"40\" y=\"275\" font-size=\"14\" text-anchor=\"middle\">응용<\/text>\n<rect class=\"box b4\" x=\"82\" y=\"230\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b4\" x=\"120\" y=\"253\" font-size=\"15\" text-anchor=\"middle\">12주<\/text>\n<text class=\"t b4\" x=\"120\" y=\"275\" font-size=\"14\" text-anchor=\"middle\">추천<\/text>\n<rect class=\"box b4\" x=\"162\" y=\"230\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b4\" x=\"200\" y=\"253\" font-size=\"15\" text-anchor=\"middle\">13주<\/text>\n<text class=\"t b4\" x=\"200\" y=\"275\" font-size=\"14\" text-anchor=\"middle\">분자<\/text>\n<rect class=\"box b4\" x=\"242\" y=\"230\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b4\" x=\"280\" y=\"253\" font-size=\"15\" text-anchor=\"middle\">14주<\/text>\n<text class=\"t b4\" x=\"280\" y=\"275\" font-size=\"14\" text-anchor=\"middle\">KG, RAG<\/text>\n<rect class=\"box b4\" x=\"322\" y=\"230\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b4\" x=\"360\" y=\"253\" font-size=\"15\" text-anchor=\"middle\">15주<\/text>\n<text class=\"t b4\" x=\"360\" y=\"275\" font-size=\"14\" text-anchor=\"middle\">정리<\/text>\n<rect class=\"box b4\" x=\"402\" y=\"230\" width=\"76\" height=\"56\" rx=\"8\"/>\n<rect class=\"hl b4\" x=\"402\" y=\"230\" width=\"76\" height=\"56\" rx=\"8\"/>\n<text class=\"tb b4\" x=\"440\" y=\"253\" font-size=\"15\" text-anchor=\"middle\">16주<\/text>\n<text class=\"tb b4\" x=\"440\" y=\"275\" font-size=\"14\" text-anchor=\"middle\">기말고사<\/text>\n<\/svg>","caption":"16주 로드맵. 진한 칸은 교수님이 어려워진다고 한 3~10주, 테두리 칸은 시험 주예요.","builds":4},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["이번 주는 그래프가 어떤 건지 간단히 보고, 지난 학기 내용을 리마인드한대요.","다음 주부터 GNN을 공부한대요. 1주차는 마이닝 한 학기의 압축 복습이에요."]},{"kind":"prof","when":"2주차 목요일 실습","lines":["이번 주까지는 할 만한데, 다음 주(3주차)부터 좀 어려워진대요."]},{"kind":"mining","src":"마이닝 1, 2, 3, 9, 10, 11, 13강","lines":["1주차 한 주에 지난 학기 강의 여러 개가 들어 있어요.","그래프 용어(1강), 인접행렬(2강), **중심성(Centrality)**(3강), 그래프 커널(9강).","DeepWalk, Node2Vec(10강), LINE(11강), 이종 그래프 **임베딩(Embedding)**(13강).","3주차 **바이스파일러-레만 검정(Weisfeiler-Lehman Test)**은 9강 WL relabeling 과 같은 아이디어예요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 3번 (GCN)","q":"a. Explain how information is propagated in a GCN layer. b. Given A and $H^{(0)}$, with $H^{(k)} = \\sigma(A H^{(k-1)})$ (ReLU), calculate the output at layer k = 1.","qko":"(a) GCN 층에서 정보가 어떻게 퍼지는지 설명하라. (b) 인접행렬 A와 처음 특징으로 1층 출력을 계산하라.","solve":["(a)는 서술이에요. 이웃 특징을 모아 내 표현을 고친다는 **메시지 패싱(Message Passing)** 이야기를 써요.","(b)는 계산이에요. **인접행렬(Adjacency Matrix)** A와 특징 행렬을 행렬곱해요.","곱한 결과에 ReLU(음수는 0)를 칸마다 적용해요.","실제 숫자 풀이는 2주차 GCN 강의에서 배워요."],"answer":"모델 하나에 (a) 서술 1개 + (b) 계산 1개. GCN은 거의 매 시험 나오는 단골이에요."},{"kind":"compare","head":"1부에서 나온 기출 (모두 가을 학기)","cols":["주제","기출"],"rows":[["얕은 **임베딩(Embedding)**","2025 중간 1번 Node2vec, 2번 LINE, 2023 중간 2번 Node2vec"],["정규화 인접행렬","2023 중간 1번"],["GCN","2025 중간 3번, 2024 중간 1번, 2024 기말 1번, 2023 중간 4번"],["표현력","2024 기말 5번 GIN, 6번 GNN-AK, 2023 기말 5번 GIN"]]},{"kind":"warn","head":"표현력은 올해 중간고사 범위일 수 있어요","items":["예전엔 GIN, GNN-AK 같은 **표현력(Expressive Power)** 문제가 기말에 나왔어요.","올해 일정표에선 3주차라 중간고사 전이에요. 일정표로 본 추측이니 시험 범위는 공지를 확인하세요."]},{"kind":"check","q":"GNN의 공통 틀 **메시지 패싱(Message Passing)**의 순서로 맞는 것은?","choices":["모으고, 받고, 고친다","이웃에게 받고, 모으고, 나와 합쳐 고친다","고치고, 받고, 모은다"],"a":1,"why":"메시지(받기), 집계(모으기), 업데이트(고치기) 순서예요."}],"pass4":[]},{"p":7,"title":"강의 일정 2부: 병목, 확장성, 강건성 (4~6주)","terms":["Homophily","Heterophily","Over-smoothing","Over-squashing","Under-reaching","Skip Connection","Attention","Graph Attention Network","Graph Pooling","Scalability","Neighborhood Explosion","Sampling"],"pass1":[{"kind":"say","lines":["2부는 그래프 신경망을 실제로 써 볼 때 부딪히는 벽 세 가지예요.","4주차는 이웃 이야기를 너무 여러 번 섞으면 모두 똑같아지는 문제예요.","5주차는 이웃마다 중요한 정도가 다르다는 점을 반영하는 방법이에요.","6주차는 그래프가 너무 커서 계산량을 감당하기 어려운 문제예요."]},{"kind":"analogy","head":"의견을 계속 섞으면 모두 같은 말을 해요","scene":"반 친구 30명이 좋아하는 음식 이야기를 해요. 처음엔 저마다 좋아하는 게 달라요. 옆 친구 의견을 듣고 내 의견을 고치는 걸 수십 번 되풀이하면 모두 같은 말을 하게 돼요. 그래서 4주차에는 여러 번 섞어도 각자 개성이 남게 하는 방법을 배워요.","map":[["친구 한 명","노드 한 개"],["옆 친구 의견을 듣고 고치기 한 번","이웃 정보 섞기 한 번(층 하나)"],["모두 같은 말을 하게 되는 것","**과잉 평활화(Over-smoothing)**"]]},{"kind":"say","lines":["5주차처럼 이웃마다 귀 기울이는 정도를 다르게 주는 걸 **어텐션(Attention)**이라고 해요.","6주차는 친구의 친구의 친구까지 챙기면 사람 수가 순식간에 불어나는 문제예요.","아주 큰 그래프에서도 배울 수 있는 힘을 **확장성(Scalability)**이라고 해요."]}],"pass2":[{"kind":"look","head":"2부: 병목, 확장성, 강건성","boxes":[{"x":0.03,"y":0.12,"w":0.2,"h":0.05,"say":"2부 제목: 병목, 확장성, 강건성이에요."},{"x":0.07,"y":0.18,"w":0.45,"h":0.22,"say":"4주차: 깊은 GNN. 동질성과 이질성, 과평활, 과압축, 도달 부족, 해결책이에요."},{"x":0.07,"y":0.41,"w":0.55,"h":0.16,"say":"5주차: 어텐션 GNN(GAT, 이종 그래프 어텐션)과 계층적 그래프 풀링이에요."},{"x":0.07,"y":0.58,"w":0.53,"h":0.23,"say":"6주차: **확장성(Scalability)**. 이웃 폭발 문제와 노드 단위, 서브그래프 단위 샘플링이에요."}]},{"kind":"points","head":"4주차 용어","items":["**동질성(Homophily)**: 끼리끼리 연결돼 이웃끼리 라벨이 비슷해요. **이질성(Heterophily)**은 반대예요.","**과잉 평활화(Over-smoothing)**: 층을 많이 쌓아 계속 섞으면 모든 노드 벡터가 비슷해져요.","**과잉 압축(Over-squashing)**: 먼 곳의 많은 정보가 작은 벡터 하나로 눌려 손실돼요.","**도달 부족(Under-reaching)**: 층이 모자라 먼 노드 정보가 아예 닿지 못해요.","해결책: DropEdge(엣지 무작위로 빼기), **스킵 연결(Skip Connection)**(앞 층 값을 뒤에 더하기), 재배선."]},{"kind":"points","head":"5, 6주차 용어","items":["**어텐션(Attention)**: 이웃마다 귀 기울일 정도를 학습해요. 대표가 **그래프 어텐션 네트워크(Graph Attention Network)**예요.","**그래프 풀링(Graph Pooling)**: 노드를 단계적으로 묶어 큰 그래프를 요약해요(DiffPool, SAGPool).","**이웃 폭발(Neighborhood Explosion)**: 층이 늘 때마다 봐야 할 이웃 수가 곱으로 불어나요.","**샘플링(Sampling)**: 이웃을 몇 개만 뽑거나(GraphSAGE), 그래프를 조각내요(ClusterGCN, GraphSAINT)."]},{"kind":"steps","head":"**이웃 폭발(Neighborhood Explosion)** 숫자로 보기","given":"모든 노드가 이웃 3명씩, 겹치는 이웃은 없다고 해요.","steps":["1층: 3명","2층: 3 × 3 = 9명","3층: 3 × 3 × 3 = 27명","5층: 3을 다섯 번 곱해 243명","이웃이 수백 명이면 금방 그래프 전체를 봐야 해요."],"answer":"그래서 **샘플링(Sampling)**으로 이웃을 몇 개만 뽑거나 그래프를 잘라요."},{"kind":"figure","head":"2부의 세 벽","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb b1\" x=\"80\" y=\"30\" font-size=\"16\" text-anchor=\"middle\">4주: 깊게 쌓으면<\/text>\n<circle class=\"n2 b1\" cx=\"26\" cy=\"80\" r=\"16\"/>\n<circle class=\"n3 b1\" cx=\"62\" cy=\"80\" r=\"16\"/>\n<circle class=\"n4 b1\" cx=\"98\" cy=\"80\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"134\" cy=\"80\" r=\"16\"/>\n<line class=\"e b1\" x1=\"80\" y1=\"104\" x2=\"80\" y2=\"140\"/>\n<polygon class=\"arrow b1\" points=\"80,150 74,138 86,138\"/>\n<circle class=\"n b1\" cx=\"26\" cy=\"174\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"62\" cy=\"174\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"98\" cy=\"174\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"134\" cy=\"174\" r=\"16\"/>\n<text class=\"t b1\" x=\"80\" y=\"222\" font-size=\"15\" text-anchor=\"middle\">모두 비슷해져요<\/text>\n<text class=\"tm b1\" x=\"80\" y=\"246\" font-size=\"14\" text-anchor=\"middle\">Over-smoothing<\/text>\n<text class=\"tb b2\" x=\"240\" y=\"30\" font-size=\"16\" text-anchor=\"middle\">5주: 이웃마다<\/text>\n<line class=\"e2 b2\" x1=\"240\" y1=\"150\" x2=\"190\" y2=\"80\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"150\" x2=\"290\" y2=\"80\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"150\" x2=\"300\" y2=\"200\"/>\n<circle class=\"n2 b2\" cx=\"240\" cy=\"150\" r=\"18\"/>\n<text class=\"tl b2\" x=\"240\" y=\"155\" font-size=\"15\" text-anchor=\"middle\">A<\/text>\n<circle class=\"n b2\" cx=\"190\" cy=\"80\" r=\"16\"/>\n<circle class=\"n b2\" cx=\"290\" cy=\"80\" r=\"16\"/>\n<circle class=\"n b2\" cx=\"300\" cy=\"200\" r=\"16\"/>\n<text class=\"tb b2\" x=\"196\" y=\"126\" font-size=\"14\" text-anchor=\"middle\">0.6<\/text>\n<text class=\"t b2\" x=\"282\" y=\"118\" font-size=\"14\" text-anchor=\"middle\">0.3<\/text>\n<text class=\"t b2\" x=\"250\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">0.1<\/text>\n<text class=\"tm b2\" x=\"240\" y=\"250\" font-size=\"14\" text-anchor=\"middle\">중요도를 학습 (GAT)<\/text>\n<text class=\"tb b3\" x=\"400\" y=\"30\" font-size=\"15\" text-anchor=\"middle\">6주: 그래프가 크면<\/text>\n<line class=\"e b3\" x1=\"400\" y1=\"72\" x2=\"350\" y2=\"135\"/>\n<line class=\"e b3\" x1=\"400\" y1=\"72\" x2=\"400\" y2=\"135\"/>\n<line class=\"e b3\" x1=\"400\" y1=\"72\" x2=\"450\" y2=\"135\"/>\n<circle class=\"n2 b3\" cx=\"400\" cy=\"72\" r=\"16\"/>\n<circle class=\"n3 b3\" cx=\"350\" cy=\"135\" r=\"16\"/>\n<circle class=\"n3 b3\" cx=\"400\" cy=\"135\" r=\"16\"/>\n<circle class=\"n3 b3\" cx=\"450\" cy=\"135\" r=\"16\"/>\n<text class=\"t b3\" x=\"400\" y=\"185\" font-size=\"14\" text-anchor=\"middle\">1층: 3개<\/text>\n<text class=\"t b3\" x=\"400\" y=\"207\" font-size=\"14\" text-anchor=\"middle\">2층: 9개<\/text>\n<text class=\"t b3\" x=\"400\" y=\"229\" font-size=\"14\" text-anchor=\"middle\">3층: 27개<\/text>\n<text class=\"tm b3\" x=\"400\" y=\"251\" font-size=\"14\" text-anchor=\"middle\">곱으로 불어나요<\/text>\n<\/svg>","caption":"과잉 평활화, 이웃마다 다른 중요도, 이웃 폭발. 2부의 세 벽이에요. 가운데 0.6, 0.3, 0.1 은 A가 이웃마다 귀 기울이는 비율이에요.","builds":3},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["GNN을 배운 뒤 깊게 하는 법, 어텐션 적용법, 확장성 개선법을 순서대로 배운대요.","바로 4주, 5주, 6주의 순서예요."]}],"pass3":[{"kind":"compare","head":"2025 가을 중간 12문항 중 9문항이 이 세 주였어요","cols":["주차","문제","계산 모양"],"rows":[["4주 깊은 GNN","7번 JKNet, 8번 GCNII, 9번 DeepGCN","정규화 인접행렬, 층별 출력, 잔차 더하기"],["5주 어텐션","10번 GAT, 11번 GATv2, 12번 HAN","어텐션 점수와 가중합, 메타패스"],["6주 확장성","4번 GraphSAGE, 5번 ClusterGCN, 6번 GraphSAINT","이웃 평균 후 이어 붙이기, ReLU"]]},{"kind":"exam","src":"2025 가을 중간 9번 (DeepGCN) (a)","q":"How does DeepGCN mitigate the over-smoothing problem as depth increases?","qko":"DeepGCN은 깊어질수록 생기는 과잉 평활화 문제를 어떻게 줄이나요?","solve":["**과잉 평활화(Over-smoothing)**: 층이 깊어지면 노드 벡터가 다 비슷해지는 문제예요.","문제의 식 $H^{(k)} = \\sigma(AH^{(k-1)}) + H^{(k-1)}$ 에서 끝의 $+H^{(k-1)}$ 을 봐요.","이전 층 값을 그대로 더하는 잔차 연결, 즉 **스킵 연결(Skip Connection)**이에요.","그래서 각 층이 이전 표현을 잃지 않아요."],"answer":"It adds a residual connection, so each layer keeps its previous representation."},{"kind":"warn","head":"기출 모델 이름과 올해 일정표","items":["JKNet, GCNII, DeepGCN 은 올해 일정표에 직접 적혀 있지 않아요.","셋 다 **스킵 연결(Skip Connection)** 계열이라 4주차 해결책에 들어갈 가능성이 높아요.","올해 3~10주가 많이 바뀌었으니 올해 슬라이드 모델을 기준으로 준비하세요."]},{"kind":"check","q":"**과잉 평활화(Over-smoothing)**의 뜻으로 맞는 것은?","choices":["층을 많이 쌓으면 모든 노드 벡터가 비슷해지는 현상","먼 노드 정보가 아예 닿지 못하는 현상","층마다 이웃 수가 곱으로 불어나는 현상"],"a":0,"why":"둘째는 **도달 부족(Under-reaching)**, 셋째는 **이웃 폭발(Neighborhood Explosion)**이에요."},{"kind":"check","q":"**동질성(Homophily)**의 뜻으로 맞는 것은?","choices":["끼리끼리 연결돼 이웃끼리 라벨이 비슷한 성질","서로 다른 것끼리 연결되는 성질","그래프가 너무 커지는 성질"],"a":0,"why":"둘째는 **이질성(Heterophily)**이에요. GCN처럼 이웃을 섞는 모델은 **동질성(Homophily)**이 강할 때 잘 돼요."}],"pass4":[]},{"p":8,"title":"강의 일정 2부 계속: 설명 가능성, 강건성, 중간고사","terms":["Explainability","Generalizability","Robustness","Adversarial Attack","Midterm Exam"],"pass1":[{"kind":"say","lines":["7주차에는 두 가지를 배워요.","그래프 신경망이 왜 그런 답을 냈는지 보여 주는 힘, 이걸 **설명 가능성(Explainability)**이라고 해요.","누가 몰래 연결을 바꿔 속이려 해도 답이 흔들리지 않는 성질은 **강건성(Robustness)**이에요.","그리고 8주차에는 학기 중간에 보는 첫 시험, **중간고사(Midterm Exam)**를 봐요."]},{"kind":"say","lines":["예를 들어 가짜 계정이 친구 관계를 꾸며서 스팸 걸러내기를 피하려 할 수 있어요.","이런 속임수에도 답이 쉽게 바뀌지 않게 만드는 법을 배워요."]}],"pass2":[{"kind":"look","head":"2부 계속과 중간고사","boxes":[{"x":0.07,"y":0.18,"w":0.47,"h":0.22,"say":"7주차: 설명 가능성, 일반화, 강건성. GNNExplainer, 적대적 공격, 방어 기법이에요."},{"x":0.07,"y":0.46,"w":0.18,"h":0.06,"say":"8주차: **중간고사(Midterm Exam)**. 이 줄만 빨간 글씨예요."}]},{"kind":"points","head":"7주차 용어","items":["**설명 가능성(Explainability)**: 답에 결정적이었던 엣지와 특징을 작은 부분그래프로 보여 줘요(GNNExplainer, PGExplainer).","**적대적 공격(Adversarial Attack)**: 엣지를 몰래 더하거나 빼고 특징을 바꿔 모델을 속여요.","예: 가짜 계정이 친구 관계를 조작해 스팸 탐지를 피하는 식이에요.","**강건성(Robustness)**: 그런 조작이 있어도 답이 쉽게 흔들리지 않는 성질이에요.","**일반화 가능성(Generalizability)**: 학습 때 못 본 그래프나 노드에서도 잘 맞히는 능력이에요."]},{"kind":"figure","head":"어려운 구간과 시험 위치","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<polyline class=\"hl b1\" points=\"66,92 66,82 297,82 297,92\" fill=\"none\"/>\n<text class=\"tb b1\" x=\"181\" y=\"68\" font-size=\"15\" text-anchor=\"middle\">3~10주: 어려워지는 구간<\/text>\n<rect class=\"box\" x=\"8\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"22\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<rect class=\"box\" x=\"37\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"51\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<rect class=\"box2\" x=\"66\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"80\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<rect class=\"box2\" x=\"95\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"109\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<rect class=\"box2\" x=\"124\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"138\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">5<\/text>\n<rect class=\"box2\" x=\"153\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"167\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">6<\/text>\n<rect class=\"box2\" x=\"182\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"196\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">7<\/text>\n<rect class=\"box2\" x=\"211\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"tb\" x=\"225\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">8<\/text>\n<rect class=\"box2\" x=\"240\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"254\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">9<\/text>\n<rect class=\"box2\" x=\"269\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"283\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">10<\/text>\n<rect class=\"box\" x=\"298\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"312\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">11<\/text>\n<rect class=\"box\" x=\"327\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"341\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">12<\/text>\n<rect class=\"box\" x=\"356\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"370\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">13<\/text>\n<rect class=\"box\" x=\"385\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"399\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">14<\/text>\n<rect class=\"box\" x=\"414\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"t\" x=\"428\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">15<\/text>\n<rect class=\"box\" x=\"443\" y=\"100\" width=\"28\" height=\"44\" rx=\"4\"/>\n<text class=\"tb\" x=\"457\" y=\"128\" font-size=\"14\" text-anchor=\"middle\">16<\/text>\n<polyline class=\"e b2\" points=\"8,152 8,162 210,162 210,152\" fill=\"none\"/>\n<text class=\"t b2\" x=\"109\" y=\"186\" font-size=\"14\" text-anchor=\"middle\">1~7주: 중간고사 전<\/text>\n<polyline class=\"e b2\" points=\"240,152 240,162 442,162 442,152\" fill=\"none\"/>\n<text class=\"t b2\" x=\"341\" y=\"186\" font-size=\"14\" text-anchor=\"middle\">9~15주: 기말고사 전<\/text>\n<rect class=\"hl b3\" x=\"235\" y=\"97\" width=\"32\" height=\"50\" rx=\"4\"/>\n<rect class=\"hl b3\" x=\"438\" y=\"97\" width=\"32\" height=\"50\" rx=\"4\"/>\n<text class=\"tb b3\" x=\"225\" y=\"232\" font-size=\"15\" text-anchor=\"middle\">8주 중간고사<\/text>\n<text class=\"tb b3\" x=\"472\" y=\"232\" font-size=\"15\" text-anchor=\"end\">16주 기말고사<\/text>\n<\/svg>","caption":"16주 중 어려워지는 3~10주와 두 시험의 위치예요.","builds":3},{"kind":"prof","when":"2주차 목요일 실습","lines":["기출도 다 볼 수 있고 ChatGPT가 예상 문제를 잘 뽑아 줘서 다들 시험을 너무 잘 봤대요.","그래서 내용을 많이 업데이트하고 최신 모델도 많이 넣었대요.","10주까지는 빡셀 예정이고, 분량보다 이해가 어려울 거래요.","11주 이후는 응용이라 부를 만한 내용이래요. 매주 밀리지 않는 게 핵심이에요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 시험지 첫머리 + 8번 (GCNII) (a)","q":"Students should write in English for evaluation. (GCNII) a) Two major components introduced to overcome the depth limitation?","qko":"평가를 위해 영어로 쓸 것. GCNII가 GCN의 깊이 한계를 넘으려고 도입한 두 요소는?","solve":["시험지 맨 위에 영어로 답하라는 안내가 있었어요.","문항은 12개, 제목이 모두 모델 이름이었어요(Node2vec부터 HAN까지).","8번은 (a) 서술, (b) 정규화 인접행렬 계산, (c) 1층 출력 계산이었어요.","(a)는 두 요소 이름을 영어로 짧게 쓰면 돼요."],"answer":"Initial residual connection and identity mapping."},{"kind":"warn","head":"7주차와 슬라이드 오타","items":["7주차 **설명 가능성(Explainability)**, **적대적 공격(Adversarial Attack)**은 올해 새 주제라 기출이 없어요.","왜 필요한가, 어떻게 동작하나를 서술로 설명할 수 있게 준비하세요.","영어 원본의 \"Generaliability\" 는 **일반화 가능성(Generalizability)** 의 오타예요."]},{"kind":"check","q":"**중간고사(Midterm Exam)** 답안은 어떤 언어로 쓰나요? (2025 가을 기준)","choices":["한국어","영어","아무 언어나"],"a":1,"why":"시험지에 \"Students should write in English for evaluation.\" 이라고 적혀 있었어요."}],"pass4":[]},{"p":9,"title":"강의 일정 3부: 고급 구조 (9~11주)","terms":["Graph Transformer","Self-Attention","Message Passing","Over-squashing","Positional Encoding","Diffusion Model","Spatio-temporal GNN"],"pass1":[{"kind":"say","lines":["3부는 조금 더 발전된 방법 세 가지예요.","9주차에는 이웃만이 아니라 모든 노드를 한꺼번에 보는 방법을 배워요.","이 방법을 쓰는 모델을 **그래프 트랜스포머(Graph Transformer)**라고 해요."]},{"kind":"analogy","head":"옆자리 친구 말만 듣기와 반 전체 말 듣기","scene":"우리 반은 30명이고, 나는 옆자리 친구 2명과만 이야기해요. 멀리 앉은 친구 소식은 여러 사람을 거쳐야 겨우 들어요. 그래서 반 전체가 모여 모두의 이야기를 한 번에 들어요. 먼 친구 이야기도 바로 들을 수 있어 좋아요.","map":[["옆자리 친구하고만 이야기하기","**메시지 패싱(Message Passing)**"],["반 전체 이야기를 한 번에 듣기","**셀프 어텐션(Self-Attention)**"],["한 번에 듣는 방식을 쓰는 모델","**그래프 트랜스포머(Graph Transformer)**"]]},{"kind":"say","lines":["10주차에는 새 그래프를 만들어 내는 방법을 배워요. 예를 들면 새 분자 만들기예요.","잡음을 조금씩 섞었다가 거꾸로 걷어 내며 새 그래프를 만드는 게 **확산 모델(Diffusion Model)**이에요.","11주차에는 시간에 따라 변하는 그래프를 다뤄요. 예를 들면 도로 막힘이에요.","옆 도로 상황과 10분 전 상황을 함께 보는 방법을 **시공간 그래프 신경망(Spatio-temporal GNN)**이라고 해요."]}],"pass2":[{"kind":"look","head":"3부: 고급 구조","boxes":[{"x":0.03,"y":0.12,"w":0.12,"h":0.05,"say":"3부 제목: 고급 구조예요."},{"x":0.07,"y":0.18,"w":0.48,"h":0.22,"say":"9주차: 그래프 트랜스포머. 셀프 어텐션, PE/SE, Graphormer, SAN이에요."},{"x":0.07,"y":0.41,"w":0.37,"h":0.16,"say":"10주차: 그래프 생성 모델과 확산 모델. VGAE와 그래프 확산 모델이에요."},{"x":0.07,"y":0.58,"w":0.37,"h":0.17,"say":"11주차: **시공간 그래프 신경망(Spatio-temporal GNN)**(STGNN). 교통, 날씨, 동작 인식에 써요."}]},{"kind":"points","head":"9주차 용어","items":["**메시지 패싱(Message Passing)**은 연결된 이웃에게서만 정보를 받아요.","**셀프 어텐션(Self-Attention)**은 모든 노드가 모든 노드를 한 번에 봐요. 먼 정보도 한 층 만에 닿아요.","그래서 4주차 **과잉 압축(Over-squashing)**, 도달 부족을 피하기 좋아요.","대신 원래 이웃을 잊어요. **위치 인코딩(Positional Encoding)**과 구조 인코딩(PE/SE)으로 차수, 거리를 넣어 줘요."]},{"kind":"points","head":"10, 11주차 용어","items":["VGAE: 노드를 확률 분포 모양 벡터로 압축했다가 엣지를 복원해요. 링크 예측에도 써요.","**확산 모델(Diffusion Model)**: 노이즈를 넣었다 거꾸로 걷어 내는 법을 배워 새 그래프(새 분자)를 만들어요.","**시공간 그래프 신경망(Spatio-temporal GNN)**: 옆 도로가 막히면(공간), 10분 전에 막혔으면(시간)을 함께 봐요.","행동 인식은 사람 관절을 노드, 뼈를 엣지로 보고 시간에 따른 움직임을 읽어요."]},{"kind":"figure","head":"이웃만 보기와 모두 보기","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<line class=\"e\" x1=\"240\" y1=\"40\" x2=\"240\" y2=\"262\"/>\n<text class=\"tb b1\" x=\"120\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">메시지 패싱<\/text>\n<line class=\"e2 b1\" x1=\"120\" y1=\"140\" x2=\"60\" y2=\"85\"/>\n<line class=\"e2 b1\" x1=\"120\" y1=\"140\" x2=\"180\" y2=\"85\"/>\n<line class=\"e b1\" x1=\"60\" y1=\"85\" x2=\"55\" y2=\"205\"/>\n<line class=\"e b1\" x1=\"180\" y1=\"85\" x2=\"185\" y2=\"205\"/>\n<circle class=\"n2 b1\" cx=\"120\" cy=\"140\" r=\"18\"/>\n<text class=\"tl b1\" x=\"120\" y=\"145\" font-size=\"15\" text-anchor=\"middle\">A<\/text>\n<circle class=\"n b1\" cx=\"60\" cy=\"85\" r=\"16\"/>\n<text class=\"tl b1\" x=\"60\" y=\"90\" font-size=\"14\" text-anchor=\"middle\">B<\/text>\n<circle class=\"n b1\" cx=\"180\" cy=\"85\" r=\"16\"/>\n<text class=\"tl b1\" x=\"180\" y=\"90\" font-size=\"14\" text-anchor=\"middle\">C<\/text>\n<circle class=\"n3 b1\" cx=\"55\" cy=\"205\" r=\"16\"/>\n<text class=\"tl b1\" x=\"55\" y=\"210\" font-size=\"14\" text-anchor=\"middle\">D<\/text>\n<circle class=\"n3 b1\" cx=\"185\" cy=\"205\" r=\"16\"/>\n<text class=\"tl b1\" x=\"185\" y=\"210\" font-size=\"14\" text-anchor=\"middle\">E<\/text>\n<text class=\"t b1\" x=\"120\" y=\"255\" font-size=\"14\" text-anchor=\"middle\">A는 이웃 B, C에게서만<\/text>\n<text class=\"tb b2\" x=\"360\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">셀프 어텐션<\/text>\n<line class=\"e b2\" x1=\"300\" y1=\"85\" x2=\"295\" y2=\"205\"/>\n<line class=\"e b2\" x1=\"420\" y1=\"85\" x2=\"425\" y2=\"205\"/>\n<line class=\"e2 b2\" x1=\"360\" y1=\"140\" x2=\"300\" y2=\"85\"/>\n<line class=\"e2 b2\" x1=\"360\" y1=\"140\" x2=\"420\" y2=\"85\"/>\n<line class=\"e2 b2\" x1=\"360\" y1=\"140\" x2=\"295\" y2=\"205\"/>\n<line class=\"e2 b2\" x1=\"360\" y1=\"140\" x2=\"425\" y2=\"205\"/>\n<circle class=\"n2 b2\" cx=\"360\" cy=\"140\" r=\"18\"/>\n<text class=\"tl b2\" x=\"360\" y=\"145\" font-size=\"15\" text-anchor=\"middle\">A<\/text>\n<circle class=\"n b2\" cx=\"300\" cy=\"85\" r=\"16\"/>\n<text class=\"tl b2\" x=\"300\" y=\"90\" font-size=\"14\" text-anchor=\"middle\">B<\/text>\n<circle class=\"n b2\" cx=\"420\" cy=\"85\" r=\"16\"/>\n<text class=\"tl b2\" x=\"420\" y=\"90\" font-size=\"14\" text-anchor=\"middle\">C<\/text>\n<circle class=\"n3 b2\" cx=\"295\" cy=\"205\" r=\"16\"/>\n<text class=\"tl b2\" x=\"295\" y=\"210\" font-size=\"14\" text-anchor=\"middle\">D<\/text>\n<circle class=\"n3 b2\" cx=\"425\" cy=\"205\" r=\"16\"/>\n<text class=\"tl b2\" x=\"425\" y=\"210\" font-size=\"14\" text-anchor=\"middle\">E<\/text>\n<text class=\"t b2\" x=\"360\" y=\"255\" font-size=\"14\" text-anchor=\"middle\">모든 노드에게서 한 번에<\/text>\n<\/svg>","caption":"**메시지 패싱(Message Passing)**은 이웃에게서만, **셀프 어텐션(Self-Attention)**은 모두에게서 받아요.","builds":2},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["학기 말쯤 실제 문제에 적용하기 위한 GNN 변형들을 배운대요.","그 예로 그래프 확산(graph diffusion)을 직접 언급했어요."]},{"kind":"mining","src":"마이닝 0강 Orientation, 14강 Dynamic GRL","lines":["11주차 배경은 마이닝 14강 동적 그래프 표현 학습이에요(dynnode2vec, DynGEM).","마이닝 OT 일정표 마지막 주 추가 주제에 GNN과 그래프 트랜스포머가 있었어요.","그 맛보기 주제를 이번 학기 9주에 제대로 배워요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 7번 (Graphormer) (b) (10점)","q":"Why does injecting structural information make the model more powerful? What structural information should be considered?","qko":"구조 정보를 넣으면 왜 그래프 구조를 더 잘 잡나요? 어떤 구조 정보를 넣어야 하나요?","solve":["(a)는 in-degree, out-degree 를 조회표로 숫자로 바꿔 입력 특징에 더하는 계산이었어요.","(b)는 서술이에요. **셀프 어텐션(Self-Attention)**은 모든 노드를 보느라 원래 연결을 잊어요.","그래서 **위치 인코딩(Positional Encoding)**, 구조 인코딩으로 구조를 알려 줘야 해요.","넣을 정보의 예: 차수(in-degree, out-degree), 노드 사이 거리."],"answer":"Self-attention forgets the original edges, so structural information like node degree and distance restores the graph structure."},{"kind":"warn","head":"3부 기출 메모","items":["2023 가을 기말 6번은 랜덤워크 위치 인코딩(RWPE) 계산이었어요.","10주 생성 모델, 11주 STGNN은 확인한 기출에 계산 문제가 없었어요.","무엇을 입력받아 무엇을 만드나, 장단점은 무엇인가를 서술로 준비하세요."]},{"kind":"check","q":"**그래프 트랜스포머(Graph Transformer)**에 **위치 인코딩(Positional Encoding)**이 필요한 이유는?","choices":["계산을 빠르게 하려고","모두를 보느라 원래 누가 이웃이었는지 잊어서","노드 수를 줄이려고"],"a":1,"why":"**셀프 어텐션(Self-Attention)**으로 모든 노드가 모든 노드를 보면 원래 연결 정보가 사라져요."}],"pass4":[]},{"p":10,"title":"강의 일정 4부: GNN 응용 (12~16주)","terms":["Bipartite Graph","Recommendation System","Equivariant GNN","Knowledge Graph","GraphRAG","Final Exam"],"pass1":[{"kind":"say","lines":["4부는 그래프 신경망을 실제 생활 문제에 써 보는 부분이에요.","12주차는 좋아할 만한 상품을 골라 주는 **추천 시스템(Recommendation System)**이에요.","13주차는 원자를 노드, 화학 결합을 엣지로 보고 분자를 다뤄요.","15주차에는 한 학기를 정리하고, 16주차에 **기말고사(Final Exam)**를 봐요."]},{"kind":"analogy","head":"같은 운동화를 산 두 손님","scene":"쇼핑몰 손님 민수와 지우는 둘 다 같은 운동화를 샀어요. 민수는 모자도 샀지만, 지우가 그 모자를 좋아할지는 아직 몰라요. 둘은 산 물건이 겹치니 취향이 비슷할 가능성이 커요. 그래서 지우에게 그 모자를 추천해요.","map":[["손님과 상품","노드(손님 무리, 상품 무리)"],["손님이 상품을 샀다","엣지"],["손님과 상품 사이에만 선이 있는 그림","**이분 그래프(Bipartite Graph)**"],["지우에게 모자 추천하기","지우와 모자 사이에 선이 새로 생길지 맞히기"]]},{"kind":"say","lines":["14주차에는 '서울은 한국의 수도' 같은 사실을 점과 선으로 모은 그래프를 배워요.","이런 그래프를 **지식 그래프(Knowledge Graph)**라고 해요.","ChatGPT 같은 대화형 인공지능이 답하기 전에 지식 그래프에서 사실을 찾아보게 할 수 있어요.","이 방법을 **그래프 검색 증강 생성(GraphRAG)**이라고 해요."]}],"pass2":[{"kind":"look","head":"4부: GNN 응용","boxes":[{"x":0.07,"y":0.18,"w":0.36,"h":0.22,"say":"12주차: 추천 시스템. 이분 그래프, LightGCN, PinSage, 평가 지표예요."},{"x":0.07,"y":0.41,"w":0.4,"h":0.22,"say":"13주차: 분자 구조 학습. 분자 그래프, **등변 GNN(Equivariant GNN)**, AlphaFold 와 신약 개발이에요."},{"x":0.07,"y":0.64,"w":0.4,"h":0.16,"say":"14주차: 이종 그래프, 지식 그래프(TransE, RotatE), **그래프 검색 증강 생성(GraphRAG)**이에요."},{"x":0.07,"y":0.81,"w":0.2,"h":0.1,"say":"15주차 총정리, 16주차 **기말고사(Final Exam)**(빨간 글씨)예요."}]},{"kind":"points","head":"12주차 용어","items":["**이분 그래프(Bipartite Graph)**: 노드가 사용자와 상품 두 무리로 나뉘고, 엣지는 두 무리 사이에만 있어요.","LightGCN: GCN에서 추천에 불필요한 비선형 활성화, 가중치 행렬을 덜어 낸 가벼운 모델이에요.","PinSage: 아주 큰 그래프에서 GraphSAGE 방식 샘플링으로 추천해요.","**추천 시스템(Recommendation System)** 평가 지표: 추천 목록 윗부분에 정답이 얼마나 있나 재요."]},{"kind":"points","head":"13, 14주차 용어","items":["분자 그래프: 원자가 노드, 화학 결합이 엣지예요.","**등변 GNN(Equivariant GNN)**: 분자를 3D에서 돌리거나 옮기면 결과도 같은 방식으로 따라 변해요.","**지식 그래프(Knowledge Graph)**: (서울, 수도이다, 한국) 같은 (머리, 관계, 꼬리) 사실을 모은 그래프예요.","TransE는 머리, 관계, 꼬리를 각각 숫자 벡터로 바꿔 머리 + 관계 ≈ 꼬리(거의 같음)가 되게 배워요.","RotatE는 관계를 회전으로 표현해요.","**그래프 검색 증강 생성(GraphRAG)**: LLM이 답하기 전에 지식 그래프에서 사실을 찾아와 참고해요."]},{"kind":"figure","head":"추천은 이분 그래프","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb b1\" x=\"100\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">사용자<\/text>\n<text class=\"tb b1\" x=\"380\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">아이템<\/text>\n<line class=\"e b1\" x1=\"100\" y1=\"75\" x2=\"380\" y2=\"60\"/>\n<line class=\"e b1\" x1=\"100\" y1=\"75\" x2=\"380\" y2=\"115\"/>\n<line class=\"e b1\" x1=\"100\" y1=\"140\" x2=\"380\" y2=\"115\"/>\n<line class=\"e b1\" x1=\"100\" y1=\"140\" x2=\"380\" y2=\"170\"/>\n<line class=\"e b1\" x1=\"100\" y1=\"205\" x2=\"380\" y2=\"170\"/>\n<line class=\"e b1\" x1=\"100\" y1=\"205\" x2=\"380\" y2=\"225\"/>\n<line class=\"e2 b2\" x1=\"100\" y1=\"205\" x2=\"380\" y2=\"115\"/>\n<circle class=\"n b1\" cx=\"100\" cy=\"75\" r=\"18\"/>\n<text class=\"tl b1\" x=\"100\" y=\"80\" font-size=\"14\" text-anchor=\"middle\">U1<\/text>\n<circle class=\"n b1\" cx=\"100\" cy=\"140\" r=\"18\"/>\n<text class=\"tl b1\" x=\"100\" y=\"145\" font-size=\"14\" text-anchor=\"middle\">U2<\/text>\n<circle class=\"n b1\" cx=\"100\" cy=\"205\" r=\"18\"/>\n<text class=\"tl b1\" x=\"100\" y=\"210\" font-size=\"14\" text-anchor=\"middle\">U3<\/text>\n<circle class=\"n3 b1\" cx=\"380\" cy=\"60\" r=\"18\"/>\n<text class=\"tl b1\" x=\"380\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">I1<\/text>\n<circle class=\"n3 b1\" cx=\"380\" cy=\"115\" r=\"18\"/>\n<text class=\"tl b1\" x=\"380\" y=\"120\" font-size=\"14\" text-anchor=\"middle\">I2<\/text>\n<circle class=\"n3 b1\" cx=\"380\" cy=\"170\" r=\"18\"/>\n<text class=\"tl b1\" x=\"380\" y=\"175\" font-size=\"14\" text-anchor=\"middle\">I3<\/text>\n<circle class=\"n3 b1\" cx=\"380\" cy=\"225\" r=\"18\"/>\n<text class=\"tl b1\" x=\"380\" y=\"230\" font-size=\"14\" text-anchor=\"middle\">I4<\/text>\n<text class=\"tb b2\" x=\"240\" y=\"262\" font-size=\"15\" text-anchor=\"middle\">U3에게 I2를 추천할까?<\/text>\n<\/svg>","caption":"U1~U3은 사용자(User) 세 명, I1~I4는 아이템(Item) 네 개예요. 추천을 **이분 그래프(Bipartite Graph)**로 보면, U2와 U3가 둘 다 I3를 샀으니 U3에게 I2를 추천할 수 있어요.","builds":2},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["학기 마지막에 추천 시스템, 분자 구조 분석 활용을 보고, 마지막에 GraphRAG까지 본대요.","조금 빡빡해도 매주 양이 방대하진 않고, 이해할 수 있게 설명하겠대요."]},{"kind":"mining","src":"마이닝 6강 Link Prediction, 13강 Heterogeneous GRL","lines":["추천은 사용자와 아이템 사이에 엣지가 생길지 맞히는 링크 예측과 같은 모양이에요.","공통 이웃, Jaccard 계수가 가장 단순한 추천이에요.","14주차 이종 그래프, **지식 그래프(Knowledge Graph)**는 13강(metapath2vec, HIN2Vec)이 배경이에요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 8번 (10점)","q":"What are the main reasons why BPR loss (Bayesian Personalized Ranking loss) is commonly utilized in recommendation system models?","qko":"추천 시스템 모델에서 BPR 손실을 흔히 쓰는 주된 이유는?","solve":["계산 없이 서술만 있는 문제예요.","BPR은 점수 자체보다 아이템 사이의 순위로 배워요.","사용자가 상호작용한 아이템이 안 한 아이템보다 점수가 높아야 해요.","이 대비를 영어 한 문장으로 써요."],"answer":"BPR learns from ranking: an item the user interacted with should score higher than an item the user did not."},{"kind":"warn","head":"응용 주제의 기출 모양","items":["응용 주제는 계산 없이 서술만 나온 경우가 많았어요.","2024 가을 기말 9번 TransR과 TransE 비교, 10번 분자 구조 학습의 대조 학습 한계도 서술이었어요."]},{"kind":"check","q":"**이분 그래프(Bipartite Graph)**의 뜻으로 맞는 것은?","choices":["노드가 두 무리로 나뉘고 엣지는 두 무리 사이에만 있는 그래프","모든 노드가 서로 연결된 그래프","시간에 따라 변하는 그래프"],"a":0,"why":"사용자와 상품처럼 두 무리 사이에만 엣지가 있어요. **추천 시스템(Recommendation System)**의 기본 모양이에요."}],"pass4":[]},{"p":11,"title":"평가 기준과 성적 척도","terms":["Midterm Exam","Final Exam","Assignment","Attendance"],"pass1":[{"kind":"say","lines":["성적 100점을 네 가지로 나눠 매겨요.","**중간고사(Midterm Exam)** 30%, **기말고사(Final Exam)** 30%예요.","매주 내는 **과제(Assignment)**도 30%, 수업에 나왔는지 보는 **출석(Attendance)**이 10%예요.","교수님 말로는 시험 점수는 다들 비슷해서, 학점은 과제에서 갈린대요."]},{"kind":"say","lines":["등급 기준은 '잠정', 즉 아직 확정은 아닌 대략의 기준이에요.","80점에서 100점은 A, 60점에서 80점은 B, 60점 아래는 C예요."]}],"pass2":[{"kind":"look","head":"평가와 잠정 등급 척도","boxes":[{"x":0.04,"y":0.24,"w":0.2,"h":0.25,"say":"평가 네 줄: 중간 30%, 기말 30%, 과제 30%, **출석(Attendance)** 10%."},{"x":0.04,"y":0.5,"w":0.52,"h":0.06,"say":"모든 시험 문제는 강의 슬라이드와 과제 안에서 나와요. 두 단어가 굵어요."},{"x":0.02,"y":0.59,"w":0.3,"h":0.29,"say":"잠정 척도: A 80~100, B 60~80, C 60 아래. 잠정은 확정이 아니란 뜻이에요."},{"x":0.04,"y":0.88,"w":0.15,"h":0.06,"say":"F: 시험 결석. 점수와 상관없이 시험을 안 보면 F예요."}]},{"kind":"steps","head":"시험은 같고 **과제(Assignment)**만 다른 두 학생","given":"둘 다 중간 70, 기말 70, 출석 100점. 학생 1은 과제 100점, 학생 2는 50점이에요. 비율 30%는 점수에 0.3을, 10%는 0.1을 곱해요.","steps":["중간: 70 × 0.3 = 21 (둘 다)","기말: 70 × 0.3 = 21 (둘 다)","출석: 100 × 0.1 = 10 (둘 다)","과제: 학생 1은 100 × 0.3 = 30, 학생 2는 50 × 0.3 = 15","합계: 학생 1은 82점, 학생 2는 67점"],"answer":"학생 1은 A 구간, 학생 2는 B 구간. 과제 하나로 15점 차이예요."},{"kind":"figure","head":"성적 구성과 척도","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<text class=\"tb b1\" x=\"20\" y=\"30\" font-size=\"15\">성적 구성 (100점)<\/text>\n<rect class=\"box b1\" x=\"20\" y=\"42\" width=\"132\" height=\"46\"/>\n<text class=\"t b1\" x=\"86\" y=\"71\" font-size=\"15\" text-anchor=\"middle\">중간 30<\/text>\n<rect class=\"box b1\" x=\"152\" y=\"42\" width=\"132\" height=\"46\"/>\n<text class=\"t b1\" x=\"218\" y=\"71\" font-size=\"15\" text-anchor=\"middle\">기말 30<\/text>\n<rect class=\"box2 b1\" x=\"284\" y=\"42\" width=\"132\" height=\"46\"/>\n<text class=\"tb b1\" x=\"350\" y=\"71\" font-size=\"15\" text-anchor=\"middle\">과제 30<\/text>\n<rect class=\"box b1\" x=\"416\" y=\"42\" width=\"44\" height=\"46\"/>\n<text class=\"t b1\" x=\"438\" y=\"62\" font-size=\"14\" text-anchor=\"middle\">출석<\/text>\n<text class=\"t b1\" x=\"438\" y=\"81\" font-size=\"14\" text-anchor=\"middle\">10<\/text>\n<text class=\"tb b2\" x=\"20\" y=\"130\" font-size=\"15\">잠정 척도<\/text>\n<rect class=\"box b2\" x=\"20\" y=\"142\" width=\"264\" height=\"40\"/>\n<text class=\"t b2\" x=\"152\" y=\"168\" font-size=\"14\" text-anchor=\"middle\">C (60 아래)<\/text>\n<rect class=\"box b2\" x=\"284\" y=\"142\" width=\"88\" height=\"40\"/>\n<text class=\"t b2\" x=\"328\" y=\"168\" font-size=\"15\" text-anchor=\"middle\">B<\/text>\n<rect class=\"box2 b2\" x=\"372\" y=\"142\" width=\"88\" height=\"40\"/>\n<text class=\"tb b2\" x=\"416\" y=\"168\" font-size=\"15\" text-anchor=\"middle\">A<\/text>\n<text class=\"tm b2\" x=\"20\" y=\"202\" font-size=\"14\">0<\/text>\n<text class=\"tm b2\" x=\"284\" y=\"202\" font-size=\"14\" text-anchor=\"middle\">60<\/text>\n<text class=\"tm b2\" x=\"372\" y=\"202\" font-size=\"14\" text-anchor=\"middle\">80<\/text>\n<text class=\"tm b2\" x=\"460\" y=\"202\" font-size=\"14\" text-anchor=\"end\">100<\/text>\n<polygon class=\"arrow b3\" points=\"315,212 309,224 321,224\"/>\n<text class=\"t b3\" x=\"318\" y=\"250\" font-size=\"14\" text-anchor=\"end\">학생 2: 67<\/text>\n<polygon class=\"arrow b3\" points=\"381,212 375,224 387,224\"/>\n<text class=\"tb b3\" x=\"378\" y=\"250\" font-size=\"14\">학생 1: 82<\/text>\n<\/svg>","caption":"성적 구성과 잠정 척도. 과제가 등급 구간을 바꿔요.","builds":3},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["출석은 전자 출결, 10%라 결석이 몇 번 쌓이지 않으면 큰 영향은 없대요. 기준은 공지를 확인하세요.","중간, 기말 점수는 다들 비슷해서 과제 점수로 학점이 갈린대요.","과제만 잘 내면 다들 B+ 정도는 받아 간대요."]},{"kind":"mining","src":"마이닝 0강 Orientation","lines":["지난 학기 마이닝도 중간 30, 기말 30, 과제 30, 출석 10이었어요.","잠정 척도와 시험은 슬라이드와 과제 안에서 낸다는 문장까지 똑같았어요."]}],"pass3":[{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["주요 모델마다 메커니즘 이해 확인 문제 하나, 장단점이나 기술적 특징 서술 하나가 한 세트래요.","중간, 기말에 보통 12~13문항, 한 주 내용에서 한두 문제꼴이래요.","기출은 웹에 2023년부터 올라와 있고, 비슷한 유형으로 나온대요."]},{"kind":"points","head":"시험 모양 한눈에","items":["모델마다 계산 문제 1개 + 서술 문제 1개가 한 세트예요.","**중간고사(Midterm Exam)**, **기말고사(Final Exam)** 각각 보통 12~13문항이에요.","답은 영어로 써요. 2025 가을 중간 시험지에 적혀 있었어요.","기출은 2023년부터 공개돼 있어요. 23, 24, 25년 모양을 먼저 보세요.","단, 3~10주 내용은 올해 크게 업데이트돼 더 어려워졌어요(2주차 목요일 공지)."]},{"kind":"compare","head":"확인한 GNN 기출의 문항 수 (모두 가을 학기)","cols":["시험","문항 수","모양"],"rows":[["2023 중간","4","계산 위주"],["2023 기말","6","계산 위주"],["2024 중간","9","계산 위주, 문항당 10~15점"],["2024 기말","10","계산 + 서술 7개, 서술만 3개"],["2025 중간","12","거의 전부 (a) 서술 + (b) 계산, 영어로"]]},{"kind":"english","head":"시험지 첫머리 문장","en":"Students should write in English for evaluation.","ko":"평가를 위해 학생들은 영어로 써야 한다.","tip":"그래서 용어의 영어 표기를 정확히 외워 두세요."},{"kind":"check","q":"교수님이 말한 시험 한 세트의 모양은?","choices":["모델마다 계산 1개 + 서술 1개","모델마다 객관식 5개","과제 코드 다시 제출"],"a":0,"why":"주요 모델마다 메커니즘 계산 하나, 장단점 서술 하나예요. 중간, 기말 각 12~13문항이에요."},{"kind":"check","q":"시험 점수가 같은 두 학생의 **과제(Assignment)** 점수가 100점과 50점이면 총점 차이는?","choices":["5점","15점","50점"],"a":1,"why":"과제 비율이 30%라서 50점 차이 × 0.3 = 15점이에요."},{"kind":"warn","head":"성적에서 헷갈리기 쉬운 점","items":["척도에 80점과 60점이 위아래 구간에 겹쳐 있어, 딱 80점, 60점의 등급은 슬라이드에 없어요.","시험에 빠지면 다른 점수와 관계없이 F예요.","슬라이드와 과제 안에서 낸다는 건 과제 코드 내용도 시험 범위라는 뜻이에요."]}],"pass4":[]},{"p":12,"title":"과제","terms":["Assignment","Jupyter Notebook","Message Passing"],"pass1":[{"kind":"say","lines":["매주 목요일에는 직접 코드를 돌려 보는 실습을 해요.","실습이 끝나면 그 내용으로 짧은 **과제(Assignment)**가 나와요.","교수님 말로는 5분, 10분이면 할 수 있는 수준이래요."]},{"kind":"say","lines":["코드와 그 실행 결과를 한 파일에 같이 담는 형식이 있어요.","이걸 **주피터 노트북(Jupyter Notebook)**이라고 하고, 파일 이름 끝이 .ipynb 예요.","과제는 받은 노트북 파일을 끝까지 돌려서, 오류 없이 그 파일 그대로 내요.","PDF나 화면 캡처처럼 다른 형식으로 바꿔 내면 받지 않아요."]}],"pass2":[{"kind":"look","head":"과제 슬라이드","boxes":[{"x":0.02,"y":0.13,"w":0.5,"h":0.25,"say":"매주 한 수업(목요일)에서 실습하고, 실습 뒤에 과제를 해요."},{"x":0.05,"y":0.49,"w":0.7,"h":0.06,"say":"초록 글씨: 반드시 .ipynb(**주피터 노트북(Jupyter Notebook)**) 파일과 필요한 파일을 함께 내요."},{"x":0.05,"y":0.575,"w":0.45,"h":0.05,"say":"빨간 글씨: PDF, 스크린샷, .py 파일은 받지 않아요."},{"x":0.05,"y":0.615,"w":0.73,"h":0.09,"say":"완성되고 실행 가능해야 해요. 실행 안 한, 빈, 미완성, 오류 있는 파일은 안 받아요."}]},{"kind":"points","head":"낯선 말 풀기","items":["**주피터 노트북(Jupyter Notebook)**(.ipynb): 코드와 실행 결과가 한 파일에 같이 저장되는 형식이에요.","실행 안 한 파일: 코드만 있고 셀 아래에 결과가 안 찍힌 파일이에요.","채점하는 사람은 결과를 보고 확인해요. 결과가 보이는 상태로 저장하세요."]},{"kind":"figure","head":"과제 제출 순서","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect class=\"box b1\" x=\"10\" y=\"30\" width=\"140\" height=\"64\" rx=\"10\"/>\n<text class=\"tb b1\" x=\"80\" y=\"56\" font-size=\"15\" text-anchor=\"middle\">1 목요일 실습<\/text>\n<text class=\"t b1\" x=\"80\" y=\"80\" font-size=\"14\" text-anchor=\"middle\">.ipynb 받기<\/text>\n<line class=\"e b1\" x1=\"150\" y1=\"62\" x2=\"162\" y2=\"62\"/>\n<polygon class=\"arrow b1\" points=\"170,62 160,56 160,68\"/>\n<rect class=\"box b1\" x=\"170\" y=\"30\" width=\"140\" height=\"64\" rx=\"10\"/>\n<text class=\"tb b1\" x=\"240\" y=\"56\" font-size=\"15\" text-anchor=\"middle\">2 과제 채우기<\/text>\n<text class=\"t b1\" x=\"240\" y=\"80\" font-size=\"14\" text-anchor=\"middle\">빈칸 없이<\/text>\n<line class=\"e b1\" x1=\"310\" y1=\"62\" x2=\"322\" y2=\"62\"/>\n<polygon class=\"arrow b1\" points=\"330,62 320,56 320,68\"/>\n<rect class=\"box b1\" x=\"330\" y=\"30\" width=\"140\" height=\"64\" rx=\"10\"/>\n<text class=\"tb b1\" x=\"400\" y=\"56\" font-size=\"15\" text-anchor=\"middle\">3 전부 실행<\/text>\n<text class=\"t b1\" x=\"400\" y=\"80\" font-size=\"14\" text-anchor=\"middle\">결과가 보이게<\/text>\n<line class=\"e b2\" x1=\"400\" y1=\"94\" x2=\"400\" y2=\"130\"/>\n<polygon class=\"arrow b2\" points=\"400,140 394,128 406,128\"/>\n<rect class=\"box b2\" x=\"330\" y=\"140\" width=\"140\" height=\"64\" rx=\"10\"/>\n<text class=\"tb b2\" x=\"400\" y=\"166\" font-size=\"15\" text-anchor=\"middle\">4 에러 확인<\/text>\n<text class=\"t b2\" x=\"400\" y=\"190\" font-size=\"14\" text-anchor=\"middle\">오류 칸 없음<\/text>\n<line class=\"e b2\" x1=\"330\" y1=\"172\" x2=\"322\" y2=\"172\"/>\n<polygon class=\"arrow b2\" points=\"310,172 322,166 322,178\"/>\n<rect class=\"box2 b2\" x=\"170\" y=\"140\" width=\"140\" height=\"64\" rx=\"10\"/>\n<text class=\"tb b2\" x=\"240\" y=\"166\" font-size=\"15\" text-anchor=\"middle\">5 .ipynb 제출<\/text>\n<text class=\"t b2\" x=\"240\" y=\"190\" font-size=\"14\" text-anchor=\"middle\">형식 그대로<\/text>\n<rect class=\"box b3\" x=\"10\" y=\"140\" width=\"140\" height=\"64\" rx=\"10\"/>\n<rect class=\"hl b3\" x=\"10\" y=\"140\" width=\"140\" height=\"64\" rx=\"10\"/>\n<text class=\"tb b3\" x=\"80\" y=\"166\" font-size=\"15\" text-anchor=\"middle\">받지 않음<\/text>\n<text class=\"t b3\" x=\"80\" y=\"190\" font-size=\"14\" text-anchor=\"middle\">PDF, .py, 캡처<\/text>\n<text class=\"t b3\" x=\"240\" y=\"248\" font-size=\"15\" text-anchor=\"middle\">안 내면 0점. 늦어도 내면 8점이에요.<\/text>\n<\/svg>","caption":"과제 제출 순서. 마지막에 형식을 바꾸지 말고 .ipynb 그대로 올려요.","builds":3},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["어려운 과제가 아니고 5분, 10분 들이면 할 수 있는 수준이래요.","채점은 A, B, C로 하고, 내기만 하면 기본 점수를 받아요.","늦게 내도 8점을 주니까 안 내는 것보다 훨씬 나아요. 과제 좀 제발 내래요."]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["과제는 ipynb 파일로 올려 준대요. 실습해 보고 그 파일 그대로 올리면 돼요.","파이썬 파일이나 PDF로 올리면 문제가 생기니, 무조건 ipynb로 올리래요."]},{"kind":"mining","src":"마이닝 0강 Orientation, 1강 Introduction","lines":["지난 학기 마이닝도 매주 목요일 실습이었어요. 같은 리듬이에요.","마이닝 때는 NetworkX 로 그래프를 만들었어요.","이번에는 PyTorch 와 PyTorch Geometric 으로 GNN 층을 쌓아요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 7번 (JK Network) (b)","q":"Calculate $\\tilde{A}$, where $\\tilde{A} = D^{-1}A$ is the normalized matrix.","qko":"정규화 행렬 $\\tilde{A} = D^{-1}A$ 를 계산하라.","solve":["2주차 목요일 실습에서 교수님이 설명한 계산과 같아요.","행마다 1의 개수, 즉 그 노드의 차수를 세요.","그 행의 칸들을 차수로 나눠요. 작은 예: 행 [0, 1, 1] 은 차수 2라서 [0, 0.5, 0.5].","여기에 특징 행렬을 곱하면 이웃 평균, 즉 **메시지 패싱(Message Passing)**의 집계가 돼요."],"answer":"행마다 차수로 나눈 행렬. 같은 계산이 2025 가을 중간 8번 GCNII 에도 나와요."},{"kind":"warn","head":"제출 전 꼭 확인","items":["셀을 순서 없이 실행하면 다시 열 때 에러가 나기 쉬워요. 제출 전 Restart and Run All 로 전부 실행하세요.","캡처나 PDF로 바꿔 내면 아무리 잘해도 받지 않아요. 형식은 .ipynb 하나예요.","데이터 같은 추가 파일이 필요하면 같이 내요."]},{"kind":"check","q":"다음 중 **과제(Assignment)**로 받아 주는 파일은?","choices":["결과가 찍힌 채로 저장한 .ipynb","코드를 캡처한 스크린샷",".py 파일"],"a":0,"why":"**주피터 노트북(Jupyter Notebook)**(.ipynb) 파일만, 끝까지 실행되고 에러 없는 상태로 받아요."}],"pass4":[]},{"p":13,"title":"담당 교수 정보","terms":["Office Hour","Teaching Assistant"],"pass1":[{"kind":"say","lines":["이 수업을 가르치는 분은 이오준 교수님이고, 연구실은 T404호예요.","교수님을 찾아가 상담하는 시간을 **면담 시간(Office Hour)**이라고 해요.","이 수업은 면담 시간이 따로 정해져 있지 않아서 언제든 찾아가도 돼요.","수업 내용이나 상담할 일이 있으면 교수님께 편하게 연락하세요."]}],"pass2":[{"kind":"look","head":"담당 교수 정보","boxes":[{"x":0.02,"y":0.13,"w":0.22,"h":0.06,"say":"이오준(O-Joun Lee) 교수님이에요."},{"x":0.04,"y":0.24,"w":0.32,"h":0.19,"say":"이메일 ojlee@catholic.ac.kr, 연구실 T404, 연구실 전화 5516(내선으로 보여요)."},{"x":0.04,"y":0.44,"w":0.3,"h":0.06,"say":"**면담 시간(Office Hour)**: 정해진 시간 없이 언제든 연구실 방문 가능해요."},{"x":0.04,"y":0.52,"w":0.4,"h":0.06,"say":"수업 관련 문제는 언제든 편하게 연락하래요."}]},{"kind":"points","head":"메일 보낼 때 요령","items":["제목에 과목명(그래프 신경망)을 적어요.","본문 첫 줄에 학번과 이름을 적으면 누구의 어떤 일인지 바로 알 수 있어요.","**면담 시간(Office Hour)**이 따로 없으니 찾아가도 돼요."]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["상담할 일이 있으면 연락하래요. 서로 소식이 없는 게 좋은 일이겠죠, 라며 웃었어요.","시험 문제, 점수, 과제 채점 결과 문의는 **조교(Teaching Assistant)**에게 하래요."]},{"kind":"mining","src":"마이닝 0강 Orientation","lines":["지난 학기 그래프 마이닝도 같은 교수님, 같은 연구실 T404, 전화 5516, 같은 이메일이었어요."]}],"pass3":[{"kind":"check","q":"과제 채점 결과가 이상할 때 먼저 연락할 곳은?","choices":["교수님","**조교(Teaching Assistant)**","같은 반 친구"],"a":1,"why":"수업 내용과 상담은 교수님, 점수와 채점 문의는 조교님께 먼저 가요."}],"pass4":[]},{"p":14,"title":"조교 정보","terms":["Teaching Assistant"],"pass1":[{"kind":"say","lines":["교수님을 도와 점수, 채점, 과제 제출 문의를 받아 주는 분들이 있어요.","이런 수업 도우미를 **조교(Teaching Assistant)**라고 하고, 이 수업엔 두 분이 계세요.","두 분 모두 B348호 연구실에 있어요.","시험 점수나 과제 채점 결과가 궁금하면 조교님께 먼저 물어보세요."]}],"pass2":[{"kind":"look","head":"조교 정보","boxes":[{"x":0.02,"y":0.14,"w":0.4,"h":0.23,"say":"첫 번째 조교님 Tien-Bach-Thanh Do. 이메일 thanhdo.work@gmail.com, 연구실 B348."},{"x":0.02,"y":0.39,"w":0.4,"h":0.23,"say":"두 번째 조교님 Huu-Tuong Ho. 이메일 tuonghh@catholic.ac.kr, 연구실 B348."}]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["시험 문제, 점수, 과제 채점 결과 문의는 조교들에게 연락하래요.","과제는 A, B, C로 채점되고 늦게 내면 8점이에요. 내 점수가 이와 다르면 확인하세요."]}],"pass3":[{"kind":"warn","head":"예전 이메일 주소 주의","items":["지난 학기 마이닝 슬라이드의 Do 조교님 이메일은 osfa19730@catholic.ac.kr 였어요.","이번 학기는 thanhdo.work@gmail.com 이에요. 이번 학기 주소를 쓰세요."]}],"pass4":[]},{"p":15,"title":"질의응답","terms":["Orientation","Assignment","Jupyter Notebook"],"pass1":[{"kind":"say","lines":["마지막 쪽은 궁금한 것을 묻고 답하는 질의응답 시간이에요.","이걸로 **오리엔테이션(Orientation)**이 끝났어요."]},{"kind":"recap","items":["화요일엔 설명을 듣고, 목요일엔 실습을 하고, 매주 **과제(Assignment)**를 내요.","3주차부터 10주차까지는 올해 내용이 바뀌어 더 어려워진 구간이에요.","과제는 **주피터 노트북(Jupyter Notebook)** 파일을 끝까지 돌려서 그대로 내요. 늦더라도 꼭 내세요.","학점은 과제에서 갈리고, 모르는 건 교수님이나 조교님께 물어보면 돼요.","오늘 가장 중요한 말은 **그래프 신경망(Graph Neural Network)**이에요.","그 기본 틀인 **메시지 패싱(Message Passing)**도 꼭 기억해 두세요."]}],"pass2":[{"kind":"look","head":"질의응답","boxes":[{"x":0.23,"y":0.25,"w":0.2,"h":0.33,"say":"Q와 A 말풍선이에요. 궁금한 것을 묻는 시간이에요."}]},{"kind":"prof","when":"OT 날(9월 1일 화요일) 수업","lines":["질문 없으면 일찍 마치자고 했어요.","목요일에는 수업할 거고 과제도 있을 거래요."]}],"pass3":[{"kind":"check","q":"교수님이 올해 크게 업데이트해서 어려워진다고 한 구간은?","choices":["1~2주","3~10주","12~16주"],"a":1,"why":"기출과 ChatGPT 예상 문제로 다들 잘 봐서 3~10주를 업데이트했대요. 매주 밀리지 않게 따라가세요."},{"kind":"check","q":"기출은 몇 년 시험부터 웹에서 볼 수 있나요?","choices":["2020년","2023년","2025년만"],"a":1,"why":"교수님이 2023년부터 올라와 있으니 23, 24, 25년 모양을 확인하라고 했어요."}],"pass4":[]}]};
